INSERT OR IGNORE INTO content(id,draft,published,updated) VALUES('settings','{"heroTitle": "Đi theo ý bạn.\nVui theo cách riêng.", "heroSubtitle": "Kể Serene nghe chuyến đi bạn mong muốn. Cùng tìm lựa chọn phù hợp cho bạn và người thương.", "heroImage": "/assets/477e2195849d3060c820.jpg", "aboutTitle": "Mỗi chuyến đi bắt đầu\ntừ một cuộc trò chuyện.", "aboutBody": "Bạn thích một buổi sáng thong thả bên biển, hay muốn khám phá thật nhiều cùng cả nhà?\n\nHãy kể cho Serene về những điều bạn mong đợi. Từ điểm đến, thời gian đến nhu cầu của từng người, đó là khởi đầu để cùng chọn dịch vụ phù hợp.", "founderName": "Nguyễn Duy Hà", "founderImage": "/assets/bd07c37cb76a6acd645d.jpg", "phone": "0327 818 196", "email": "", "company": "Serene Travel", "address": "", "hours": "", "zalo": "https://zalo.me/0327818196", "cardVinpearl": "/assets/05ce3a8cc462e7bd4d60.jpg", "cardHotel": "/assets/477e2195849d3060c820.jpg", "cardTour": "/assets/a0ea3ffe7c71cd12ba28.jpg", "cardTicket": "/assets/777970735bb4d030d40a.jpg", "homeCard1Title": "Combo Vinpearl", "homeCard1Text": "Nghỉ dưỡng và vui chơi, theo cách của bạn.", "homeCard2Title": "Khách sạn / Resort", "homeCard2Text": "Tìm một nơi ở thật hợp với bạn.", "homeCard3Title": "Tour trong ngày", "homeCard3Text": "Thêm trải nghiệm cho hành trình.", "homeCard4Title": "Vé các loại", "homeCard4Text": "Bớt lo chuẩn bị, thêm vui khám phá.", "homeStep1Title": "Bạn kể, Serene lắng nghe", "homeStep1Text": "Điểm đến, thời gian và những điều bạn mong muốn ở chuyến đi.", "homeStep2Title": "Cùng chọn phương án", "homeStep2Text": "Trao đổi lựa chọn, giá và các điều kiện cụ thể trước khi quyết định.", "homeStep3Title": "Rõ ràng trước khi đặt", "homeStep3Text": "Kiểm tra lại thông tin, hạng mục dịch vụ và điều kiện áp dụng.", "homeFaq1Question": "Chưa biết chọn dịch vụ nào thì có thể liên hệ không?", "homeFaq1Answer": "Bạn có thể chọn “Mình cần Serene gợi ý thêm” trong biểu mẫu và chia sẻ điểm đến, thời gian hoặc mong muốn của mình.", "homeFaq2Question": "Vì sao chưa có giá trên website?", "homeFaq2Answer": "Giá và tình trạng dịch vụ cần được xác nhận theo ngày đi, số khách và nhu cầu cụ thể. Hãy trao đổi với Serene để nhận thông tin cho yêu cầu của bạn.", "homeFaq3Question": "Điền biểu mẫu có đồng nghĩa đã đặt dịch vụ?", "homeFaq3Answer": "Chưa. Biểu mẫu giúp bạn soạn yêu cầu tư vấn. Việc đặt dịch vụ cần được trao đổi và xác nhận riêng.", "homeServicesTitle": "Bạn đang muốn đi đâu?", "homeServicesText": "Một kỳ nghỉ thảnh thơi hay một ngày đầy trải nghiệm? Bắt đầu từ điều bạn thích.", "homeProcessTitle": "Từ ý tưởng đến chuyến đi", "homeFaqTitle": "Có thể bạn đang băn khoăn"}','{"heroTitle": "Đi theo ý bạn.\nVui theo cách riêng.", "heroSubtitle": "Kể Serene nghe chuyến đi bạn mong muốn. Cùng tìm lựa chọn phù hợp cho bạn và người thương.", "heroImage": "/assets/477e2195849d3060c820.jpg", "aboutTitle": "Mỗi chuyến đi bắt đầu\ntừ một cuộc trò chuyện.", "aboutBody": "Bạn thích một buổi sáng thong thả bên biển, hay muốn khám phá thật nhiều cùng cả nhà?\n\nHãy kể cho Serene về những điều bạn mong đợi. Từ điểm đến, thời gian đến nhu cầu của từng người, đó là khởi đầu để cùng chọn dịch vụ phù hợp.", "founderName": "Nguyễn Duy Hà", "founderImage": "/assets/bd07c37cb76a6acd645d.jpg", "phone": "0327 818 196", "email": "", "company": "Serene Travel", "address": "", "hours": "", "zalo": "https://zalo.me/0327818196", "cardVinpearl": "/assets/05ce3a8cc462e7bd4d60.jpg", "cardHotel": "/assets/477e2195849d3060c820.jpg", "cardTour": "/assets/a0ea3ffe7c71cd12ba28.jpg", "cardTicket": "/assets/777970735bb4d030d40a.jpg", "homeCard1Title": "Combo Vinpearl", "homeCard1Text": "Nghỉ dưỡng và vui chơi, theo cách của bạn.", "homeCard2Title": "Khách sạn / Resort", "homeCard2Text": "Tìm một nơi ở thật hợp với bạn.", "homeCard3Title": "Tour trong ngày", "homeCard3Text": "Thêm trải nghiệm cho hành trình.", "homeCard4Title": "Vé các loại", "homeCard4Text": "Bớt lo chuẩn bị, thêm vui khám phá.", "homeStep1Title": "Bạn kể, Serene lắng nghe", "homeStep1Text": "Điểm đến, thời gian và những điều bạn mong muốn ở chuyến đi.", "homeStep2Title": "Cùng chọn phương án", "homeStep2Text": "Trao đổi lựa chọn, giá và các điều kiện cụ thể trước khi quyết định.", "homeStep3Title": "Rõ ràng trước khi đặt", "homeStep3Text": "Kiểm tra lại thông tin, hạng mục dịch vụ và điều kiện áp dụng.", "homeFaq1Question": "Chưa biết chọn dịch vụ nào thì có thể liên hệ không?", "homeFaq1Answer": "Bạn có thể chọn “Mình cần Serene gợi ý thêm” trong biểu mẫu và chia sẻ điểm đến, thời gian hoặc mong muốn của mình.", "homeFaq2Question": "Vì sao chưa có giá trên website?", "homeFaq2Answer": "Giá và tình trạng dịch vụ cần được xác nhận theo ngày đi, số khách và nhu cầu cụ thể. Hãy trao đổi với Serene để nhận thông tin cho yêu cầu của bạn.", "homeFaq3Question": "Điền biểu mẫu có đồng nghĩa đã đặt dịch vụ?", "homeFaq3Answer": "Chưa. Biểu mẫu giúp bạn soạn yêu cầu tư vấn. Việc đặt dịch vụ cần được trao đổi và xác nhận riêng.", "homeServicesTitle": "Bạn đang muốn đi đâu?", "homeServicesText": "Một kỳ nghỉ thảnh thơi hay một ngày đầy trải nghiệm? Bắt đầu từ điều bạn thích.", "homeProcessTitle": "Từ ý tưởng đến chuyến đi", "homeFaqTitle": "Có thể bạn đang băn khoăn"}',datetime('now')); 
